<div class="admin-page-heading"><div><span class="admin-eyebrow">SERVICE CONTENT</span><p>Maintain the service information visitors see on the website.</p></div><a class="admin-button" href="<?= e(url('/admin/services/create')) ?>">＋ Add Service</a></div><section class="admin-panel"><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>SERVICE</th><th>SHORT DESCRIPTION</th><th>STATUS</th><th>ORDER</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($services as $service): ?><tr><td><strong><?= e($service['title']) ?></strong><small><?= e($service['slug']) ?></small></td><td><?= e($service['short_description']) ?></td><td><span class="status <?= $service['is_published']?'status-completed':'status-closed' ?>"><?= $service['is_published']?'Published':'Hidden' ?></span></td><td><?= e($service['sort_order']) ?></td><td class="actions-cell"><a class="table-action" href="<?= e(url('/admin/services/'.$service['id'].'/edit')) ?>">Edit</a><form method="post" action="<?= e(url('/admin/services/'.$service['id'].'/delete')) ?>" data-confirm="Delete this service?"><?= csrf_field() ?><button class="table-danger" type="submit">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></section>
